export const periodicVariableSourceInternalVoltageCoefficientsItemMin = 2;
export const periodicVariableSourceInternalVoltageCoefficientsItemMax = 2;

export const periodicVariableSourceInternalAngleCoefficientsItemMin = 2;
export const periodicVariableSourceInternalAngleCoefficientsItemMax = 2;

export const periodicVariableSourceBasePowerExclusiveMin = 0;

export const PeriodicVariableSource = zod
  .strictObject({
    id: zod.int().describe("Unique integer identifier for this component."),
    name: zod
      .string()
      .describe(
        "Name of the dynamic injection. Must equal the name of the static injection device that names it in `dynamic_injector`.",
      ),
    R_th: zod.number().describe("Source Thevenin resistance"),
    X_th: zod.number().describe("Source Thevenin reactance"),
    internal_voltage_bias: zod
      .number()
      .optional()
      .describe("a0 term of the Fourier Series for the voltage"),
    internal_voltage_frequencies: zod
      .array(zod.number())
      .optional()
      .describe("Frequencies in radians/s"),
    internal_voltage_coefficients: zod
      .array(
        zod
          .array(zod.number())
          .min(periodicVariableSourceInternalVoltageCoefficientsItemMin)
          .max(periodicVariableSourceInternalVoltageCoefficientsItemMax),
      )
      .optional()
      .describe(
        "Coefficients for terms n > 1. First component corresponds to sin and second component to cos",
      ),
    internal_angle_bias: zod
      .number()
      .optional()
      .describe("a0 term of the Fourier Series for the angle"),
    internal_angle_frequencies: zod
      .array(zod.number())
      .optional()
      .describe("Frequencies in radians/s"),
    internal_angle_coefficients: zod
      .array(
        zod
          .array(zod.number())
          .min(periodicVariableSourceInternalAngleCoefficientsItemMin)
          .max(periodicVariableSourceInternalAngleCoefficientsItemMax),
      )
      .optional()
      .describe(
        "Coefficients for terms n > 1. First component corresponds to sin and second component to cos",
      ),
    base_power: zod
      .number()
      .gt(periodicVariableSourceBasePowerExclusiveMin)
      .describe(
        "Base power for the per-unit parameters of this model. Usually equal to the `base_power` of the static injection device that names this model. Units: MVA.",
      ),
  })
  .describe(
    "This struct acts as an infinity bus with time varying phasor values magnitude and angle V(t) heta(t). Time varying functions are represented using fourier series It has no bus of its own: exactly one static injection device, with the same name, names it in its `dynamic_injector` property, and that device supplies the rest of its data.",
  );

export type PeriodicVariableSource = zod.input<typeof PeriodicVariableSource>;
export type PeriodicVariableSourceOutput = zod.output<
  typeof PeriodicVariableSource
>;

